const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',spark:'m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4L12 3z M20 2v4 M18 4h4',folder:'M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7z',image:'M4 3h16a1 1 0 0 1 1 1v16a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1z M3 16l6-6 5 5 3-3 4 4 M16 7h.01',layers:'m12 3 10 5-10 5L2 8l10-5z M2 12l10 5 10-5 M2 16l10 5 10-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3z',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 4v16 M4 12h16',arrow:'M4 12h16 m-6-6 6 6-6 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',help:'M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5 M12 17h.01 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',check:'m5 12 4 4L19 6',clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 6v6l4 2',instagram:'M7 3h10a4 4 0 0 1 4 4v10a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4V7a4 4 0 0 1 4-4z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 7h.01',chat:'M21 11a9 8 0 0 1-9 8H8l-5 3 1-6a9 8 0 0 1-1-5 9 8 0 0 1 18 0z',blog:'M5 3h14v18H5z M9 7h6 M9 11h6 M9 15h4',video:'M3 5h13v14H3z m13 6 5-4v10l-5-4',play:'m9 5 11 7-11 7V5z',pause:'M8 5v14 M16 5v14',download:'M12 3v12 m-5-5 5 5 5-5 M4 15v6h16v-6',edit:'m4 16 12-12 4 4L8 20H4v-4z M14 6l4 4',copy:'M9 9h12v12H9z M15 9V3H3v12h6',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',upload:'M12 16V3 m-5 5 5-5 5 5 M4 15v6h16v-6',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15 M16 16l5 5',close:'m5 5 14 14 M19 5 5 19',menu:'M4 6h16 M4 12h16 M4 18h16',refresh:'M20 11a8 8 0 0 0-14-5L3 9 M3 3v6h6 M4 13a8 8 0 0 0 14 5l3-3 M15 15h6v6',link:'m10 13 4-4 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',wallet:'M3 5h18v15H3z M3 5V3h14v2 M15 11h6v5h-6z M17 13.5h.01',list:'M9 6h12 M9 12h12 M9 18h12 M3 6h.01 M3 12h.01 M3 18h.01',external:'M14 3h7v7 M10 14 21 3 M10 3H3v18h18v-7',leaf:'M20 3C9 2 3 6 4 14s14 9 16-11z M4 21 14 10'};
function icon(n,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`}
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const products=[{id:'apple',name:'애플파이',img:'assets/apple.webp'},{id:'pepperoni',name:'페페로니 피자파이',img:'assets/pepperoni.webp'},{id:'blueberry',name:'블루베리파이',img:'assets/blueberry.webp'}];
const channels=[{id:'instagram',name:'인스타그램',short:'인스타',icon:'instagram'},{id:'kakao',name:'카카오톡 채널',short:'카톡채널',icon:'chat'},{id:'blog',name:'네이버 블로그',short:'블로그',icon:'blog'},{id:'youtube',name:'유튜브 쇼츠',short:'쇼츠',icon:'play'},{id:'reels',name:'인스타 릴스',short:'릴스',icon:'video'}];
const cardTitles=['우리 카페에\n디저트를 더한다면?','고객이 찾는\n메뉴부터.','우리 매장에 맞는\n공간과 동선.','커피 옆에,\n바삭한 한 조각.','우리 매장에 맞는지\n함께 확인해요.'];
const defaultCaption='우리 카페에 새로운 디저트를 더하고 싶다면?\n고객 취향, 매장 동선, 도입 조건부터 살펴보세요.\n120pie&coffee 샵인샵이 우리 매장에 맞는지 상담으로 확인해 보세요.\n\n#120pieandcoffee #120겹파이 #카페디저트 #샵인샵';
function newSample(id,name,product,audience,status='검토 대기'){return {id,name,product,audience,status,channels:channels.map(c=>c.id),goal:audience==='consumer'?'제품·매장 홍보':'샵인샵 도입 상담',topic:'우리 카페에 맞는 디저트 메뉴 추가',titles:audience==='consumer'?['커피 옆에,\n바삭한 한 조각.','오늘의 취향을\n채워보세요.','나를 위한\n달콤한 시간.','당신의 오후에,\n파이와 커피.','120pie&coffee와\n함께하는 오늘.']:[...cardTitles],caption:audience==='consumer'?'커피 한 잔에 바삭한 파이 한 조각.\n오늘의 오후를 120pie&coffee와 함께해 보세요.\n\n#120pieandcoffee #120겹파이 #파이와커피':defaultCaption,template:'yellow',textProvider:'OpenAI',imageProvider:'OpenAI',videoProvider:'Google',updated:'샘플 캠페인'}}
const defaults={brand:{name:'120pie&coffee',tone:'밝고 명확하게, 제품 사진 중심으로',description:'120겹 파이와 커피를 소개하는 디저트 브랜드',cta:'우리 매장 도입 조건 상담하기'},campaigns:[newSample('sample-1','우리 카페에 디저트를 더한다면','apple','business'),newSample('sample-2','커피와 함께하는 바삭한 오후','pepperoni','consumer','초안'),newSample('sample-3','취향을 채우는 파이 한 조각','apple','consumer')],uploads:[],budget:50000,retries:2};
let data;try{data=JSON.parse(localStorage.getItem('120studio-design-v1'))||structuredClone(defaults)}catch{data=structuredClone(defaults)}
let route=location.hash.slice(1)||'dashboard',current=data.campaigns[0]?.id,channel='instagram',cardIndex=0,sceneIndex=0,playTimer=null,playTime=0,mobileOpen=false,wizardStep=1,wizardDraft={},modalFocus=null,filter='all';
let campaign=()=>data.campaigns.find(c=>c.id===current)||data.campaigns[0];
let prod=()=>{const c=campaign(),a=[...products,...data.uploads].find(p=>p.id===(c.assetId||c.product))||products[0];return {...a,img:typeof assetSource==='function'?assetSource(a):a.img}};
function persist(){try{localStorage.setItem('120studio-design-v1',JSON.stringify(data));return true}catch{toast('저장 공간이 부족합니다. 변경 내용을 저장하지 못했습니다.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
const navs=[['dashboard','grid','대시보드'],['studio','spark','콘텐츠 제작'],['campaigns','folder','캠페인'],['assets','image','브랜드 자료실'],['templates','layers','디자인 템플릿']];
function navigate(r){if($('#modal-root').children.length)closeModal();stopVideo();route=r;mobileOpen=false;location.hash=r;render();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1)||'dashboard';if(r!==route){route=r;render()}});
function shell(content){let pageName=navs.find(n=>n[0]===route)?.[2]||({settings:'API 및 사용량',brand:'브랜드 설정'}[route])||'대시보드';return `<div class="mobile-overlay ${mobileOpen?'show':''}" data-act="menu-close"></div><aside class="sidebar ${mobileOpen?'open':''}"><a href="#dashboard" class="brandmark" style="text-decoration:none"><span class="mark">120</span><div><div class="studio">content studio<span style="color:#c4a54c">.</span></div><div class="byline">MAKE YOUR BRAND SHINE</div></div></a><button class="brand-selector" data-act="brand-switch"><span class="brand-avatar">120</span><span class="grow"><strong>${esc(data.brand.name)}</strong><small>브랜드 워크스페이스</small></span>${icon('down')}</button><div class="nav-label">WORKSPACE</div><nav class="nav">${navs.map(([r,i,n])=>`<button data-route="${r}" class="${route===r?'active':''}">${icon(i)}${n}${r==='campaigns'?`<span class="nav-count">${data.campaigns.length}</span>`:''}</button>`).join('')}</nav><div class="divider"></div><div class="nav-label">MANAGE</div><nav class="nav"><button data-route="brand" class="${route==='brand'?'active':''}">${icon('leaf')}브랜드 설정</button><button data-route="settings" class="${route==='settings'?'active':''}">${icon('settings')}API 및 사용량</button></nav><div class="sidebar-bottom"><div class="workspace-note"><span class="badge yellow">DESIGN PREVIEW</span><p>좋은 콘텐츠의 시작.</p><small>실제 제품과 브랜드 기준으로<br>우리다운 콘텐츠를 만드세요.</small></div><div class="profile"><span class="avatar">JH</span><div class="grow"><strong>김지훈</strong><small>워크스페이스 관리자</small></div><button class="icon-btn" data-act="help" aria-label="시안 안내">${icon('help')}</button></div></div></aside><main class="main"><header class="topbar"><div class="flex crumb"><button class="icon-btn mobile-menu" data-act="menu" aria-label="메뉴 열기">${icon('menu')}</button><span>워크스페이스</span>${icon('chevron')}<strong>${pageName}</strong></div><div class="flex top-actions"><span class="preview">디자인 시안 · 샘플 데이터</span><span class="badge outline"><i class="dot"></i>API 미연결</span><button class="icon-btn" data-act="notifications" aria-label="알림">${icon('bell')}</button><span class="avatar" style="width:28px;height:28px;font-size:9px">JH</span></div></header><div class="page">${content}<footer class="footnote"><span>120 CONTENT STUDIO · YOUR NEXT GOOD IDEA</span><span>화면 시연용 · 입력한 설정은 이 브라우저에 저장됩니다.</span></footer></div></main>`}
function pageHead(title,sub,actions='',eyebrow=''){return `<div class="page-head"><div>${eyebrow?`<div class="greeting"><i class="dot"></i>${eyebrow}</div>`:''}<h1>${title}</h1><p>${sub}</p></div>${actions}</div>`}
function channelDots(ids){return `<div class="channel-dots">${ids.slice(0,4).map(id=>`<span class="channel-dot" title="${channels.find(c=>c.id===id)?.name}">${icon(channels.find(c=>c.id===id)?.icon)}</span>`).join('')}</div>`}
function campaignCard(c,i){return `<button class="campaign-card" data-open="${c.id}"><div class="campaign-cover ${i%3===1?'mint':i%3===2?'cream':''}"><span class="cover-brand">120 PIE & COFFEE</span><h3>${esc(c.titles[0]).replace(/\n/g,'<br>')}</h3><img src="${i%3===2&&c.product==='apple'?'assets/lifestyle.webp':products.find(p=>p.id===c.product)?.img||products[0].img}" alt="120pie 제품 콘텐츠 예시"><span class="cover-caption">${c.audience==='business'?'우리 매장에 맞는 메뉴를 만나보세요.':'120pie&coffee와 함께하는 오늘'}</span></div><div class="campaign-meta"><div class="flex between"><span class="badge ${c.status==='검토 대기'?'yellow':c.status==='승인 완료'?'green':''}">${c.status}</span><span class="sample-tag">${c.updated==='샘플 캠페인'?'SAMPLE':'내 초안'}</span></div><h3>${esc(c.name)}</h3><div class="details"><span>${c.audience==='business'?'샵인샵·창업 상담':'제품·매장 홍보'} · ${c.channels.length}개 채널</span>${channelDots(c.channels)}</div></div></button>`}
function dashboard(){const review=data.campaigns.filter(c=>c.status==='검토 대기').length;return `${pageHead('좋은 콘텐츠를 만드는 하루.','아이디어 하나로, 우리 브랜드의 다음 이야기를 준비하세요.',`<button class="btn primary" data-act="new">${icon('plus')}새 캠페인</button>`,'120pie&coffee 워크스페이스')}<section class="hero"><div class="hero-copy"><div class="eyebrow">ONE IDEA, EVERY CHANNEL</div><h2>우리 브랜드의 이야기를,<br><span>더 많은 곳에.</span></h2><p>글부터 이미지, 짧은 영상까지.<br>하나의 캠페인에서 자연스럽게 이어지는 콘텐츠를 만드세요.</p><button class="btn dark" data-act="new">콘텐츠 만들기 ${icon('arrow')}</button></div><div class="hero-visual" aria-hidden="true"><div class="hero-card"><div class="tiny-logo">120 PIE & COFFEE</div><h3>커피 옆에,<br>바삭한 한 조각.</h3><img src="assets/apple.webp" alt=""></div><div class="hero-card second"><img src="assets/lifestyle.webp" alt=""></div><div class="float-label">${icon('instagram')}브랜드에 맞는 카드뉴스</div><div class="float-label bottom">${icon('play')}짧지만, 기억에 남는 이야기</div></div></section><div class="stats">${[[data.campaigns.length,'개의 샘플·초안','전체 캠페인','folder'],[review,'개 콘텐츠','검토 대기','clock'],[4+data.uploads.length,'개 이미지','브랜드 자료','image'],['미연결','','생성 API','link']].map(([v,u,l,i])=>`<div class="stat"><div><div class="stat-label">${l}</div><div class="stat-value" style="${typeof v==='string'?'font-size:20px':''}">${v}<em>${u}</em></div></div><span class="stat-icon">${icon(i)}</span></div>`).join('')}</div><div class="section-title"><div><h2>이어서 만들어볼까요?</h2><p>작업 중인 캠페인에서 다음 아이디어를 이어가세요.</p></div><button class="btn ghost sm" data-route="campaigns">캠페인 전체보기 ${icon('arrow')}</button></div><div class="campaign-grid">${data.campaigns.slice(0,3).map(campaignCard).join('')}</div><div class="bottom-grid"><section class="panel"><div class="flex between"><h3>제작 전, 한 번 더 확인해요</h3><span class="sample-tag">WORKFLOW</span></div><div class="task-row"><span class="task-dot">${icon('image')}</span><div class="grow"><strong>실제 제품 사진으로 시작하기</strong><small>애플 · 페페로니 · 블루베리 제품 원본</small></div><button class="icon-btn" data-route="assets" aria-label="브랜드 자료실 열기">${icon('chevron')}</button></div><div class="task-row"><span class="task-dot">${icon('check')}</span><div class="grow"><strong>한 문장으로 핵심 메시지 정하기</strong><small>고객과 목적이 분명한 콘텐츠</small></div><button class="icon-btn" data-act="new" aria-label="새 캠페인 시작">${icon('chevron')}</button></div><div class="task-row"><span class="task-dot">${icon('lock')}</span><div class="grow"><strong>API 연결과 사용 한도 확인하기</strong><small>연결 전에는 샘플로 제작 흐름을 체험해요</small></div><button class="icon-btn" data-route="settings" aria-label="API 설정 열기">${icon('chevron')}</button></div></section><section class="panel"><div class="flex between"><h3>우리다운 콘텐츠의 기준</h3><button class="btn ghost sm" data-route="brand">설정 ${icon('chevron')}</button></div><div class="brand-note"><span class="swatch"></span><div><strong>밝게, 명확하게, 먹음직스럽게.</strong><p>실제 제품 사진을 중심으로<br>120pie의 노란색 포인트를 더해요.</p></div></div><div class="spacer"></div><div class="notice">${icon('leaf')}샵인샵 상담과 매장 방문 콘텐츠는 고객과 목적을 구분해 제작합니다.</div></section></div>`}
function artCard(index=cardIndex,cls='',p=prod()){const c=campaign();let style=c.template==='green'?'art-green':c.template==='ivory'?'art-ivory':index===1?'art-green':index===2?'art-ivory':index===3?'art-photo':'';return `<div class="art-card ${style} ${cls}" id="art-preview"><div class="art-brand"><span>120 PIE & COFFEE</span><span>THE GOOD LAYERS</span></div><h2>${esc(c.titles[index])}</h2><p>${c.audience==='consumer'?'일상의 작은 순간을 더 맛있게.':index===0?'우리 매장에 맞는 디저트,\n120pie&coffee와 함께 알아보세요.':index===4?'도입 조건을 상담으로 확인해 보세요.':'일상의 작은 순간을 더 맛있게.'}</p><span class="art-circle"></span><img class="art-product" src="${index===3?'assets/lifestyle.webp':p.img}" alt="${esc(p.name)}"><div class="art-bottom"><span>120pie&coffee</span><span>${String(index+1).padStart(2,'0')} / 05</span></div></div>`}
function providerRows(){const c=campaign();return ['text','image','video'].map((t,i)=>`<div class="engine-row"><span>${['기획·텍스트','이미지 제작','영상 제작'][i]}</span><select aria-label="${['기획','이미지','영상'][i]} API 선택" data-provider="${t}">${(t==='video'?['Google']:['OpenAI','Google']).map(p=>`<option ${c[t+'Provider']===p?'selected':''}>${p}</option>`).join('')}</select></div>`).join('')}
function studio(){const c=campaign();const isVideo=['youtube','reels'].includes(channel);return `${pageHead('콘텐츠 제작실','브랜드의 한 가지 이야기를, 채널에 맞는 다양한 콘텐츠로.',`<div class="flex"><button class="btn ghost" data-act="new">${icon('plus')}새 캠페인</button><button class="btn" data-act="save">${icon('check')}초안 저장</button></div>`)}<div class="studio-layout"><section class="panel brief-panel"><div class="flex between"><h3>캠페인 브리프</h3><span class="badge outline">${c.updated==='샘플 캠페인'?'샘플':'내 초안'}</span></div><div class="divider"></div><div class="field"><label for="campaign-name">캠페인 이름</label><input id="campaign-name" type="text" value="${esc(c.name)}" data-field="name"></div><div class="field"><label>누구에게 전할까요?</label><div class="segmented"><button data-audience="business" class="${c.audience==='business'?'active':''}">사업자·파트너</button><button data-audience="consumer" class="${c.audience==='consumer'?'active':''}">일반 소비자</button></div></div><div class="field"><label>소개할 제품·서비스</label><div class="product-picks">${products.map(p=>`<button class="product-pick ${c.product===p.id?'active':''}" data-product="${p.id}"><img src="${p.img}" alt="">${p.name.replace(' 피자','')}</button>`).join('')}</div></div><div class="field"><label for="topic">이번 콘텐츠의 주제</label><textarea id="topic" data-field="topic">${esc(c.topic)}</textarea></div><div class="field"><label>제작 채널</label><div class="channel-checks">${channels.map(ch=>`<button class="${c.channels.includes(ch.id)?'active':''}" data-toggle-channel="${ch.id}" aria-pressed="${c.channels.includes(ch.id)}">${icon(ch.icon)}${ch.short}</button>`).join('')}</div></div><div class="field"><label for="creation-template">디자인 스타일</label><select id="creation-template" data-template-select><option value="yellow" ${c.template==='yellow'?'selected':''}>120 시그니처 · 옐로우</option><option value="green" ${c.template==='green'?'selected':''}>내추럴 · 세이지</option><option value="ivory" ${c.template==='ivory'?'selected':''}>클린 · 아이보리</option></select></div><div class="field"><label>제작 엔진 <span class="muted" style="font-weight:400">· 선택 시연</span></label>${providerRows()}</div><div class="notice">${icon('lock')}예상 비용은 API 연결 후 확인할 수 있어요. 지금은 샘플 미리보기로 진행합니다.</div><button class="btn primary full" data-act="generate" style="margin-top:15px">${icon('spark')}미리보기 생성</button><div class="sample-tag" style="text-align:center;margin-top:9px">실제 API 호출과 비용 발생 없음</div></section><section class="panel preview-panel"><div class="preview-header"><div class="flex between"><h3>채널별 콘텐츠</h3><span class="badge ${c.status==='승인 완료'?'green':'yellow'}"><i class="dot"></i>${c.status}</span></div><div class="tabs">${channels.map(ch=>`<button class="tab ${channel===ch.id?'active':''}" data-channel="${ch.id}">${icon(ch.icon)}${ch.short}</button>`).join('')}</div></div><div class="preview-tools"><span class="small muted" style="font-size:10px">${isVideo?'스토리보드 · 9:16 · 20초':channel==='blog'?'본문과 이미지 배치 미리보기':`${channel==='kakao'?'카드뉴스 · 1:1':'피드 카드 · 4:5'} · ${cardIndex+1} / 5`}</span><div class="flex"><button class="icon-btn" data-act="copy" aria-label="본문 복사">${icon('copy')}</button><button class="icon-btn" data-act="edit-title" aria-label="문구 수정">${icon('edit')}</button></div></div><div class="preview-stage" id="preview-stage">${isVideo?videoPreview():channel==='blog'?blogPreview():`${artCard()}<div class="preview-info"><div class="eyebrow">YOUR BRAND,<br>YOUR STORY.</div><h3>${cardIndex===0?'첫 장에서 시선을 끌고,':'하나의 카드에는,'}<br>${cardIndex===0?'다음 이야기를 기대하게.':'하나의 메시지를.'}</h3><p>선택한 상품의 사진과<br>디자인 설정을 사용하는<br>편집 미리보기입니다.</p><span class="badge outline">${icon('image')}제품 원본 사용</span><p style="margin-top:16px;font-size:9px">아래 문구를 바꾸면<br>미리보기에 바로 반영돼요.</p></div>`}</div>${isVideo||channel==='blog'?'':`<div class="thumb-strip">${cardTitles.map((_,i)=>`<button class="thumb ${cardIndex===i?'active':''}" data-card="${i}" aria-label="${i+1}번 카드 선택"><span>0${i+1}</span><img src="${prod().img}" alt=""></button>`).join('')}</div>`}<div class="caption-box"><div class="editor-title-row"><span class="grow flex">${icon('edit')}<strong style="font-size:11px">${isVideo?'현재 장면 자막':channel==='blog'?'블로그 제목':'카드 제목'}</strong></span><button class="btn sm ghost" data-act="shorten">짧은 문구 적용 ${icon('spark')}</button></div><textarea aria-label="미리보기 제목 수정" id="edit-title" class="editor-title-input">${esc(isVideo?sceneTexts()[sceneIndex]:channel==='blog'?c.name:c.titles[cardIndex])}</textarea><div class="flex between" style="margin-top:17px"><strong style="font-size:11px">${channel==='blog'?'블로그 본문':'게시글'}</strong><button class="btn ghost sm" data-act="copy">${icon('copy')}복사</button></div><textarea id="caption-edit" aria-label="게시글 수정">${esc(c.caption)}</textarea></div><div class="studio-footer"><p>${isVideo?'장면 전환을 확인하는 화면 시연입니다.':'제품·문구를 확인한 뒤 디자인을 승인하세요.'}</p><div class="flex"><button class="btn sm" data-act="download">${icon('download')}${isVideo?'장면표 저장':channel==='blog'?'본문 저장':'이미지 저장'}</button><button class="btn primary sm" data-act="approve">${icon('check')}디자인 승인</button></div></div></section></div>`}
let sceneTexts=()=>campaign().scenes||(campaign().audience==='consumer'?['커피 옆에,\n바삭한 한 조각.','오늘의 취향을\n채워보세요.','나를 위한\n달콤한 시간.','120pie&coffee와\n함께하는 오늘.']:['우리 카페에\n디저트를 더한다면?','고객이 찾는\n메뉴부터.','공간과 준비 동선까지\n함께 확인해요.','우리 매장에 맞는지\n상담해 보세요.']);
function videoPreview(){return `<div class="video-wrap"><div class="phone ${playTimer?'playing':''}"><img id="video-image" src="${sceneIndex===1?prod().img:'assets/lifestyle.webp'}" style="${sceneIndex===1?'object-fit:contain':''}" alt="영상 장면 시연"><span class="phone-logo">120 PIE & COFFEE</span><button class="play-btn" data-act="play" aria-label="${playTimer?'미리보기 일시정지':'스토리보드 미리보기 재생'}">${icon(playTimer?'pause':'play')}</button><div class="phone-caption">${esc(sceneTexts()[sceneIndex])}</div><div class="video-time"><span id="video-time">00:${String(playTime).padStart(2,'0')}</span><div class="progress-track"><div class="progress-fill" style="width:${playTime*5}%"></div></div><span>00:20</span></div></div><div class="scene-list">${(campaign().audience==='consumer'?['시선을 끄는 첫 장면','제품의 매력','파이와 커피','브랜드로 연결']:['시선을 끄는 첫 장면','제품의 매력','도입 전 확인','상담으로 연결']).map((t,i)=>`<button class="scene ${sceneIndex===i?'active':''}" data-scene="${i}"><span class="scene-no">0${i+1}</span><div><strong>${t}</strong><small>${['0–3초','3–8초','8–15초','15–20초'][i]}</small></div></button>`).join('')}</div></div>`}
function blogPreview(){return `<article class="blog-preview"><span class="blog-name">120pie&coffee · 브랜드 이야기</span><h2 id="blog-heading">${esc(campaign().name)}</h2><p>${campaign().audience==='consumer'?'잠깐 쉬어가는 오후, 파이와 커피를 함께 즐겨보세요.<br>오늘의 취향에 맞는 디저트를 만나보세요.':'카페의 다음 메뉴를 고민하고 계신가요?<br>새로운 디저트를 더하기 전, 우리 매장에 맞는 조건을 차근차근 살펴보세요.'}</p><img src="${prod().img}" alt="${prod().name}"><h3>${campaign().audience==='consumer'?'파이 한 조각으로 즐기는 시간':'고객이 찾는 메뉴부터 살펴보세요'}</h3><p id="blog-text">${esc(typeof captionFor==='function'?captionFor('blog'):campaign().caption).replace(/\n/g,'<br>')}</p></article>`}
function campaignsPage(){let cs=filter==='all'?data.campaigns:data.campaigns.filter(c=>c.status===filter);return `${pageHead('캠페인','아이디어부터 완성까지, 한곳에서 이어가는 브랜드 이야기.',`<button class="btn primary" data-act="new">${icon('plus')}새 캠페인</button>`)}<div class="filterbar"><div class="tabs no-margin">${[['all','전체'],['초안','초안'],['검토 대기','검토 대기'],['승인 완료','승인 완료']].map(([id,label])=>`<button class="tab ${filter===id?'active':''}" data-filter="${id}">${label}${id==='all'?` <span class="badge">${data.campaigns.length}</span>`:''}</button>`).join('')}</div><div class="search-box">${icon('search')}<input type="text" placeholder="캠페인 검색" aria-label="캠페인 검색" id="campaign-search"></div></div><div class="campaign-grid" id="campaign-results">${cs.length?cs.map(campaignCard).join(''):'<div class="empty">아직 이 상태의 캠페인이 없어요.</div>'}</div><div class="spacer"></div><div class="notice">${icon('help')}샘플 캠페인을 열어 편집하거나, 새 캠페인을 만들어 제작 흐름을 체험해 보세요. 디자인 승인은 외부 게시와 별개입니다.</div>`}
function assetsPage(){const list=[...products.map(p=>({...p,type:'제품 원본',source:'실제 제품 누끼 · 투명 배경'})),{id:'lifestyle',name:'애플파이와 라떼',img:'assets/lifestyle.webp',type:'연출 이미지',source:'생성 이미지 · 실제 매장 증빙 아님'},...data.uploads];return `${pageHead('브랜드 자료실','우리 제품의 모습 그대로, 콘텐츠의 시작이 되는 자료들.',`<button class="btn primary" data-act="upload">${icon('upload')}이미지 추가</button><input type="file" id="asset-upload" accept="image/png,image/jpeg,image/webp" multiple hidden>`)}<div class="filterbar"><div class="tabs no-margin"><button class="tab active">전체 이미지 <span class="badge">${list.length}</span></button></div><div class="search-box">${icon('search')}<input id="asset-search" type="text" placeholder="자료 이름 검색" aria-label="자료 이름 검색"></div></div><div class="asset-grid">${list.map(a=>`<article class="asset" data-asset-name="${esc(a.name)}"><div class="asset-img ${a.id==='lifestyle'?'photo':''}"><img src="${a.img}" alt="${esc(a.name)}"><span class="badge ${a.type==='제품 원본'?'green':'outline'}">${a.type}</span></div><div class="asset-body"><h3>${esc(a.name)}</h3><p>${a.source||'이 브라우저에 저장한 이미지'}</p><div class="flex between"><span class="sample-tag">${a.id==='lifestyle'?'REFERENCE IMAGE':'BRAND ASSET'}</span><button class="btn sm" data-asset="${a.id}">크게 보기</button></div></div></article>`).join('')}</div><div class="spacer"></div><div class="notice">${icon('lock')}자료 추가는 이 브라우저 안에서만 동작합니다. 서버 업로드와 브랜드별 접근 권한은 API 개발 단계에서 연결합니다.</div>`}
function templatesPage(){return `${pageHead('디자인 템플릿','익숙한 브랜드의 인상, 새로운 콘텐츠에도 일관되게.')}<div class="template-grid">${[['yellow','120 시그니처','제품과 메시지가 선명하게 보이는 옐로우 포인트.'],['green','내추럴 세이지','차분한 컬러로 제품의 질감에 집중하는 디자인.'],['ivory','클린 아이보리','여백과 간결한 문구로 편안하게 전달하는 디자인.']].map(([id,title,desc])=>{const c=campaign(),prev=c.template;c.template=id;const art=artCard(0);c.template=prev;return `<div class="template">${art}<h3>${title}</h3><p>${desc}</p><button class="btn full" data-use-template="${id}">이 템플릿으로 만들기 ${icon('arrow')}</button></div>`}).join('')}</div>`}
function settingsPage(){return `${pageHead('API 및 사용량','제작에 필요한 엔진과 사용 한도를 관리하세요.',`<span class="badge outline">${icon('lock')}관리자 설정</span>`)}<div class="settings-grid"><section class="panel"><h3>제작 엔진 연결</h3><p class="settings-note">기획, 이미지, 영상에 맞는 API를 선택해 사용합니다.</p>${[['OpenAI','GPT · 기획 / 글 / 이미지','spark'],['Google','Gemini · 이미지 / 영상','layers']].map(([name,desc,i])=>`<div class="provider"><div class="flex"><span class="provider-logo">${icon(i)}</span><div class="grow"><h3>${name}</h3><p>${desc}</p></div><span class="badge">미연결</span></div><div class="flex between" style="margin-top:17px"><span class="small muted" style="font-size:10px">등록된 API 키 없음</span><button class="btn sm" data-connect="${name}">연결 안내 ${icon('chevron')}</button></div></div>`).join('')}<div class="settings-note">${icon('lock')} API 키는 서버에서만 관리합니다. 이 디자인 시안에서는 실제 키를 입력하거나 저장하지 않습니다.</div></section><section class="panel"><div class="flex between"><h3>이번 달 API 사용량</h3><span class="badge">미연결</span></div><div class="usage-value">— <span style="font-size:13px;color:#99a28c;letter-spacing:0">원</span></div><p class="small muted">API 연결 후 실제 사용량을 확인할 수 있어요.</p><div class="usage-track"></div><div class="settings-fields"><div class="field"><label for="budget">월 사용 한도 · 원</label><input type="number" id="budget" min="1000" step="1000" value="${data.budget}"></div><div class="field"><label for="retry-limit">최대 재생성 횟수</label><select id="retry-limit">${[1,2,3,5].map(n=>`<option value="${n}" ${data.retries===n?'selected':''}>${n}회</option>`).join('')}</select></div></div><button class="btn full" data-act="save-budget" style="margin-top:17px">사용 설정 저장</button><p class="settings-note">화면 설정만 저장됩니다. 실제 과금 제한은 서버 연동 후 적용합니다.</p></section></div><div class="spacer"></div><section class="panel"><div class="flex between"><div><h3>브라우저 시연 데이터</h3><p class="settings-note" style="margin-top:7px">샘플 캠페인, 수정한 문구, 업로드한 이미지와 설정을 관리합니다.</p></div><button class="btn sm" data-act="reset">시연 데이터 초기화</button></div></section>`}
function brandPage(){return `${pageHead('브랜드 설정','콘텐츠마다 흔들리지 않는, 우리 브랜드의 기준.')}<section class="panel brand-form"><div class="brand-preview"><span class="brand-avatar" style="width:55px;height:55px;font-size:20px;background:#f5ce57">120</span><div><h2>${esc(data.brand.name)}</h2><p class="settings-note" style="margin:4px 0 0">브랜드 이미지 · 제품 중심 · 옐로우 포인트</p></div></div><div class="brand-form-grid"><div class="field"><label for="brand-name">브랜드 이름</label><input type="text" id="brand-name" value="${esc(data.brand.name)}"></div><div class="field"><label for="brand-tone">브랜드 말투</label><input type="text" id="brand-tone" value="${esc(data.brand.tone)}"></div><div class="field wide"><label for="brand-description">브랜드 소개</label><textarea id="brand-description">${esc(data.brand.description)}</textarea></div><div class="field wide"><label for="brand-cta">기본 상담 유도 문구</label><input type="text" id="brand-cta" value="${esc(data.brand.cta)}"></div></div><div class="notice">${icon('check')}가격, 매장 수, 도입 조건은 승인된 자료가 있을 때만 콘텐츠에 사용합니다. 브랜드 설정은 이 브라우저에 저장됩니다.</div><div class="flex" style="justify-content:flex-end;margin-top:19px"><button class="btn primary" data-act="save-brand">브랜드 설정 저장</button></div></section>`}
function render(){if(!['dashboard','studio','campaigns','assets','templates','settings','brand','publish'].includes(route))route='dashboard';$('#app').innerHTML=shell(({dashboard,studio,campaigns:campaignsPage,assets:assetsPage,templates:templatesPage,settings:settingsPage,brand:brandPage,publish:publishPage}[route])());if(channel==='kakao'&&route==='studio'){const art=$('#art-preview');if(art){art.style.aspectRatio='1';art.style.maxWidth='320px';art.querySelector('h2')&&(art.querySelector('h2').style.marginTop='20px')}}}
function openModal(title,body,footer=''){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-act="close-modal" aria-label="닫기">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input,.modal button')?.focus(),20)}
function closeModal(){if(window.generationTimer){clearTimeout(window.generationTimer);window.generationTimer=null}$('#modal-root').innerHTML='';document.body.style.overflow='';modalFocus?.isConnected&&modalFocus.focus()}
function newWizard(){wizardStep=1;wizardDraft={name:'',audience:'business',topic:'',channels:channels.map(c=>c.id)};drawWizard()}
function drawWizard(){const step=`<div class="steps"><span class="${wizardStep===1?'active':''}"><b>1</b>캠페인 브리프</span><i></i><span class="${wizardStep===2?'active':''}"><b>2</b>채널 선택</span><i></i><span><b>3</b>미리보기</span></div>`;let body=wizardStep===1?`${step}<p class="intro">어떤 이야기를 전하고 싶으신가요?<br>목적이 분명할수록 콘텐츠의 방향도 선명해집니다.</p><div class="field"><label for="new-name">캠페인 이름</label><input type="text" id="new-name" placeholder="예: 우리 카페에 디저트 메뉴 추가" value="${esc(wizardDraft.name)}" maxlength="60"></div><div class="field"><label for="new-audience">주요 고객</label><select id="new-audience"><option value="business" ${wizardDraft.audience==='business'?'selected':''}>기존 카페 운영자 · 샵인샵 상담</option><option value="consumer" ${wizardDraft.audience==='consumer'?'selected':''}>일반 소비자 · 제품과 매장 홍보</option></select></div><div class="field"><label for="new-topic">콘텐츠 주제</label><textarea id="new-topic" placeholder="전달하고 싶은 핵심 메시지를 적어주세요.">${esc(wizardDraft.topic)}</textarea></div>`:`${step}<p class="intro">${esc(wizardDraft.name)}<br>제작할 채널을 선택하세요. 이후 제작실에서도 바꿀 수 있어요.</p><div class="field"><label>제작할 채널</label><div class="channel-checks">${channels.map(c=>`<button class="${wizardDraft.channels.includes(c.id)?'active':''}" data-wizard-channel="${c.id}">${icon(c.icon)}${c.name}</button>`).join('')}</div></div><div class="field"><label for="new-product">먼저 보여줄 제품</label><select id="new-product">${products.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></div><div class="notice">${icon('spark')}샘플 카드와 장면표로 제작 과정을 체험합니다. API 연결 전에는 실제 콘텐츠를 자동 생성하지 않습니다.</div>`;openModal('새 캠페인 만들기',body,`<button class="btn ghost" data-act="${wizardStep===1?'close-modal':'wizard-back'}">${wizardStep===1?'취소':'이전'}</button><button class="btn primary" data-act="${wizardStep===1?'wizard-next':'wizard-create'}">${wizardStep===1?'다음 단계':'샘플 제작 시작'} ${icon('arrow')}</button>`)}
function generatePreview(){const c=campaign();openModal('미리보기를 준비하고 있어요',`<div class="progress-modal"><div class="spinner"></div><h3>하나의 이야기를, 여러 채널로.</h3><p>샘플 구성으로 제작 흐름을 보여드립니다.</p><div class="progress-checks"><div>${icon('check')}브랜드와 제품 자료 확인</div><div>${icon('check')}채널별 샘플 구성 불러오기</div><div>${icon('clock')}미리보기 화면 준비</div></div></div>`);window.generationTimer=setTimeout(()=>{window.generationTimer=null;closeModal();c.status='검토 대기';persist();channel=c.channels[0]||'instagram';cardIndex=0;navigate('studio');toast('샘플 미리보기가 준비됐어요. 문구와 디자인을 수정해 보세요.');},1200)}
function stopVideo(){if(playTimer)clearInterval(playTimer);playTimer=null}
function setScene(n){sceneIndex=n;const stage=$('#preview-stage');if(stage){stage.innerHTML=videoPreview();const edit=$('#edit-title');if(edit)edit.value=sceneTexts()[sceneIndex]}}
function playVideo(){if(playTimer){stopVideo();setScene(sceneIndex);return}if(playTime>=20)playTime=0;playTimer=setInterval(()=>{playTime++;let n=playTime<3?0:playTime<8?1:playTime<15?2:3;if(n!==sceneIndex)setScene(n);if($('#video-time'))$('#video-time').textContent='00:'+String(playTime).padStart(2,'0');if($('.progress-fill'))$('.progress-fill').style.width=playTime*5+'%';if(playTime>=20){stopVideo();setScene(3)}},1000);setScene(sceneIndex)}
function invalidate(){if(campaign().status==='승인 완료'){campaign().status='검토 대기';const b=$('.preview-header .badge');if(b){b.className='badge yellow';b.innerHTML='<i class="dot"></i>검토 대기'}}persist()}
function downloadText(filename,text,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function drawWrapped(ctx,text,x,y,width,lineHeight){const lines=[];String(text).split('\n').forEach(part=>{let line='';for(const ch of part){if(ctx.measureText(line+ch).width>width&&line){lines.push(line);line=ch}else line+=ch}lines.push(line)});for(const line of lines){ctx.fillText(line,x,y);y+=lineHeight}return y}
async function downloadCard(){toast('이미지를 준비하고 있어요.');await document.fonts.ready;const c=campaign(),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=channel==='kakao'?1080:1350;const ctx=canvas.getContext('2d'),h=canvas.height;const base=c.template==='green'?'#e7eddf':c.template==='ivory'?'#f7f2e8':cardIndex===1?'#e7eddf':cardIndex===2?'#f7f2e8':'#f1ca64';ctx.fillStyle=base;ctx.fillRect(0,0,1080,h);const img=new Image();img.src=cardIndex===3?'assets/lifestyle.webp':prod().img;await img.decode();if(cardIndex===3){const s=Math.max(1080/img.width,h/img.height);ctx.drawImage(img,(1080-img.width*s)/2,(h-img.height*s)/2,img.width*s,img.height*s);const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#f4ecdde0');g.addColorStop(.85,'#f4ecdd00');ctx.fillStyle=g;ctx.fillRect(0,0,1080,h)}else{ctx.fillStyle=c.template==='green'?'#d1ddc3':'#ffe7a2';ctx.beginPath();ctx.arc(930,h-180,520,0,Math.PI*2);ctx.fill();const s=Math.min(1200/img.width,(h*.46)/img.height);ctx.save();ctx.translate(530,h-350);ctx.rotate(-.12);ctx.drawImage(img,-img.width*s/2,-img.height*s/2,img.width*s,img.height*s);ctx.restore()}ctx.fillStyle='#2e3028';ctx.font='800 35px "Noto Sans KR",sans-serif';ctx.fillText('120 PIE & COFFEE',82,112);ctx.font='500 22px "Noto Sans KR",sans-serif';ctx.fillText('THE GOOD LAYERS',755,108);ctx.font='800 94px "Noto Sans KR",sans-serif';let y=drawWrapped(ctx,c.titles[cardIndex],82,290,920,126);ctx.font='400 31px "Noto Sans KR",sans-serif';drawWrapped(ctx,c.audience==='consumer'?'일상의 작은 순간을 더 맛있게.':cardIndex===4?'도입 조건을 상담으로 확인해 보세요.':'우리 매장에 맞는 디저트,\n120pie&coffee와 함께 알아보세요.',82,y+22,900,50);ctx.font='500 25px "Noto Sans KR",sans-serif';ctx.fillText('120pie&coffee',82,h-60);ctx.fillText(`0${cardIndex+1} / 05`,905,h-60);canvas.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`120pie-${channel}-card-${cardIndex+1}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('현재 카드 이미지를 저장했습니다.');},'image/png')}
async function copyCaption(){try{await navigator.clipboard.writeText(campaign().caption);toast('게시글을 복사했어요.')}catch{const t=$('#caption-edit');if(t){t.select();toast('본문을 선택했어요. 복사 단축키를 눌러주세요.')}else toast('제작실의 게시글에서 직접 복사할 수 있어요.')}}
document.addEventListener('click',async e=>{let el=e.target.closest('button,[data-act],[data-route]');if(!el)return;if(el.dataset.route){navigate(el.dataset.route);return}if(el.dataset.open){current=el.dataset.open;channel=campaign().channels[0]||'instagram';cardIndex=0;navigate('studio');return}if(el.dataset.channel){stopVideo();channel=el.dataset.channel;render();return}if(el.dataset.card!==undefined){cardIndex=Number(el.dataset.card);render();return}if(el.dataset.product){campaign().product=el.dataset.product;delete campaign().assetId;invalidate();render();return}if(el.dataset.audience){campaign().audience=el.dataset.audience;invalidate();render();return}if(el.dataset.toggleChannel){let cs=campaign().channels,id=el.dataset.toggleChannel;if(cs.includes(id)&&cs.length===1){toast('최소 한 개의 채널을 선택해주세요.');return}campaign().channels=cs.includes(id)?cs.filter(x=>x!==id):[...cs,id];if(!campaign().channels.includes(channel))channel=campaign().channels[0];invalidate();render();return}if(el.dataset.filter){filter=el.dataset.filter;render();return}if(el.dataset.useTemplate){campaign().template=el.dataset.useTemplate;invalidate();navigate('studio');toast('선택한 디자인을 적용했어요.');return}if(el.dataset.scene!==undefined){stopVideo();playTime=[0,3,8,15][Number(el.dataset.scene)];setScene(Number(el.dataset.scene));return}if(el.dataset.wizardChannel){const id=el.dataset.wizardChannel;wizardDraft.channels=wizardDraft.channels.includes(id)?wizardDraft.channels.filter(x=>x!==id):[...wizardDraft.channels,id];el.classList.toggle('active',wizardDraft.channels.includes(id));return}if(el.dataset.asset){const a=[...products,{id:'lifestyle',name:'애플파이와 라떼',img:'assets/lifestyle.webp'},...data.uploads].find(x=>x.id===el.dataset.asset);openModal(esc(a.name),`<img src="${a.img}" alt="${esc(a.name)}" style="width:100%;max-height:60vh;object-fit:contain;background:#f5f5ed;border-radius:8px"><p class="settings-note">${a.id==='lifestyle'?'생성 연출 이미지 · 실제 매장이나 고객 경험의 증빙이 아닙니다.':'브랜드 콘텐츠 제작에 사용하는 이미지입니다.'}</p>`);return}if(el.dataset.connect){openModal(`${el.dataset.connect} 연결 안내`,`<div class="notice">${icon('lock')}API 키는 서버의 비밀 저장소에서 등록합니다.</div><p class="intro" style="margin-top:20px">현재는 화면 디자인 시안으로 외부 API와 연결되어 있지 않습니다. 실제 개발에서는 서버 연결 상태만 이 화면에 표시하고 키 원문은 다시 노출하지 않습니다.</p><div class="provider"><div class="flex between"><strong>연결 상태</strong><span class="badge">미연결</span></div></div>`,`<span class="small muted">이 화면에 실제 키를 입력하지 않습니다.</span><button class="btn primary" data-act="close-modal">확인</button>`);return}
const a=el.dataset.act;if(a==='menu'){mobileOpen=true;render()}else if(a==='menu-close'){mobileOpen=false;render()}else if(a==='new')newWizard();else if(a==='close-modal')closeModal();else if(a==='save'){persist();toast('이 브라우저에 초안을 저장했어요.')}else if(a==='generate')generatePreview();else if(a==='play')playVideo();else if(a==='edit-title'){$('#edit-title')?.focus();$('#edit-title')?.scrollIntoView({behavior:'smooth',block:'center'})}else if(a==='copy')copyCaption();else if(a==='download'){if(['youtube','reels'].includes(channel))downloadText(exportPrefix()+'-storyboard.txt',sceneTexts().map((t,i)=>`${['0–3초','3–8초','8–15초','15–20초'][i]}\n${t}`).join('\n\n')+'\n\n화면 시연용 장면표 · 실제 영상 파일 아님');else if(channel==='blog')downloadText(exportPrefix()+'-blog.txt',fullText('blog'));else await downloadCard()}else if(a==='approve'){campaign().status='승인 완료';persist();render();toast('디자인을 승인했어요. 실제 SNS에는 게시되지 않습니다.')}else if(a==='shorten'){const c=campaign();if(['youtube','reels'].includes(channel)){c.scenes=[...sceneTexts()];c.scenes[sceneIndex]=['디저트를 더한다면?','우리 고객의 취향.','공간과 동선까지.','상담으로 확인해요.'][sceneIndex]}else if(channel==='blog')c.name='우리 카페의 다음 디저트';else c.titles[cardIndex]=['우리 카페의\n다음 디저트.','고객의 취향부터.','공간과 동선까지.','바삭한 오후.','상담으로\n확인해요.'][cardIndex];invalidate();render();toast('준비된 짧은 문구를 적용했어요.')}else if(a==='wizard-next'){wizardDraft.name=$('#new-name').value.trim();wizardDraft.topic=$('#new-topic').value.trim();wizardDraft.audience=$('#new-audience').value;if(!wizardDraft.name){$('#new-name').focus();toast('캠페인 이름을 적어주세요.');return}wizardStep=2;drawWizard()}else if(a==='wizard-back'){wizardStep=1;drawWizard()}else if(a==='wizard-create'){if(!wizardDraft.channels.length){toast('최소 한 개의 채널을 선택해주세요.');return}const c=newSample('draft-'+Date.now(),wizardDraft.name,$('#new-product').value,wizardDraft.audience,'초안');c.topic=wizardDraft.topic||'우리 브랜드에 맞는 새로운 콘텐츠';c.channels=[...wizardDraft.channels];c.updated='내 초안';if(c.audience==='consumer'){c.titles=['커피 옆에,\n바삭한 한 조각.','오늘의 취향을\n채워보세요.','나를 위한\n달콤한 시간.','당신의 오후에,\n파이와 커피.','120pie&coffee와\n함께하는 오늘.'];c.caption='커피 한 잔에 바삭한 파이 한 조각.\n오늘의 오후를 120pie&coffee와 함께해 보세요.\n\n#120pieandcoffee #120겹파이 #파이와커피'}data.campaigns.unshift(c);current=c.id;persist();generatePreview()}else if(a==='upload')$('#asset-upload').click();else if(a==='save-budget'){let n=Number($('#budget').value);if(!Number.isFinite(n)||n<1000){toast('월 한도는 1,000원 이상으로 입력해주세요.');return}data.budget=n;data.retries=Number($('#retry-limit').value);persist();toast('사용 설정을 저장했어요. 실제 과금에는 아직 적용되지 않습니다.')}else if(a==='save-brand'){const n=$('#brand-name').value.trim();if(!n){toast('브랜드 이름을 입력해주세요.');return}data.brand={name:n,tone:$('#brand-tone').value,description:$('#brand-description').value,cta:$('#brand-cta').value};persist();render();toast('브랜드 기준을 저장했어요.')}else if(a==='reset')openModal('시연 데이터를 초기화할까요?','<p class="intro">이 브라우저에 저장한 캠페인 수정 내용, 추가한 이미지, 브랜드 설정을 지우고 처음 샘플로 돌아갑니다.</p>',`<button class="btn" data-act="close-modal">취소</button><button class="btn primary" data-act="confirm-reset">초기화</button>`);else if(a==='confirm-reset'){data=structuredClone(defaults);current=data.campaigns[0]?.id;persist();closeModal();navigate('dashboard');toast('처음 샘플로 돌아왔어요.')}else if(a==='brand-switch')openModal('브랜드 워크스페이스',`<div class="brand-preview"><span class="brand-avatar">120</span><div class="grow"><strong>${esc(data.brand.name)}</strong><p class="settings-note" style="margin-top:3px">현재 선택된 브랜드</p></div>${icon('check')}</div><p class="intro">120pie를 첫 브랜드로 제작한 화면입니다. 다른 브랜드 추가는 실제 프로그램 개발 단계에서 연결합니다.</p>`,`<button class="btn ghost" data-route="brand" data-act="close-and-brand">브랜드 설정</button><button class="btn primary" data-act="close-modal">확인</button>`);else if(a==='notifications')openModal('확인할 작업',`<div class="task-row"><span class="task-dot">${icon('clock')}</span><div><strong>디자인 검토 대기 ${data.campaigns.filter(c=>c.status==='검토 대기').length}건</strong><small>샘플·내 초안 기준</small></div></div><div class="task-row"><span class="task-dot">${icon('link')}</span><div><strong>실제 생성 API 미연결</strong><small>현재는 샘플로 제작 흐름을 체험합니다.</small></div></div>`);else if(a==='help')openModal('120 콘텐츠 스튜디오 사용 안내',`<p class="intro">120pie의 SNS 콘텐츠 제작 프로그램을 미리 체험하는 화면입니다.</p><div class="task-row"><span class="badge">01</span><strong>새 캠페인에서 고객과 주제를 선택하세요.</strong></div><div class="task-row"><span class="badge">02</span><strong>제작실에서 채널과 디자인을 바꿔보세요.</strong></div><div class="task-row"><span class="badge">03</span><strong>문구를 수정하고 카드 PNG를 저장하세요.</strong></div><div class="notice" style="margin-top:18px">실제 생성·SNS 게시·영상 MP4 출력은 API 개발 단계에서 연결합니다. 지금 저장되는 설정은 이 브라우저에만 남습니다.</div>`);
});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){campaign()[t.dataset.field]=t.value;invalidate()}if(t.id==='edit-title'){const c=campaign();if(['youtube','reels'].includes(channel)){c.scenes=[...sceneTexts()];c.scenes[sceneIndex]=t.value;if($('.phone-caption'))$('.phone-caption').textContent=t.value}else if(channel==='blog'){c.name=t.value;if($('#blog-heading'))$('#blog-heading').textContent=t.value}else{c.titles[cardIndex]=t.value;if($('#art-preview h2'))$('#art-preview h2').textContent=t.value}invalidate()}if(t.id==='caption-edit'){campaign().caption=t.value;invalidate();if($('#blog-text'))$('#blog-text').innerHTML=esc(t.value).replace(/\n/g,'<br>')}if(t.id==='campaign-search'){const cs=data.campaigns.filter(c=>(filter==='all'||c.status===filter)&&c.name.toLowerCase().includes(t.value.toLowerCase()));$('#campaign-results').innerHTML=cs.length?cs.map(campaignCard).join(''):'<div class="empty">검색 결과가 없어요. 다른 이름으로 찾아보세요.</div>'}if(t.id==='asset-search'){document.querySelectorAll('[data-asset-name]').forEach(a=>a.hidden=!a.dataset.assetName.toLowerCase().includes(t.value.toLowerCase()))}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.provider){campaign()[t.dataset.provider+'Provider']=t.value;persist();toast('제작 엔진 선택을 저장했어요. 현재는 미연결 상태입니다.')}if(t.hasAttribute('data-template-select')){campaign().template=t.value;invalidate();render()}if(t.id==='asset-upload'){for(const f of t.files){if(!['image/png','image/jpeg','image/webp'].includes(f.type)){toast('PNG, JPG, WebP 이미지를 선택해주세요.');continue}if(f.size>12*1024*1024){toast('이미지는 12MB 이하로 추가해주세요.');continue}try{const img=new Image(),u=URL.createObjectURL(f);img.src=u;await img.decode();const cv=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(img.width,img.height));cv.width=Math.round(img.width*scale);cv.height=Math.round(img.height*scale);cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);URL.revokeObjectURL(u);data.uploads.push({id:'upload-'+Date.now()+'-'+data.uploads.length,name:f.name,img:cv.toDataURL('image/webp',.85),type:'추가한 자료',source:'브라우저 저장 · '+cv.width+'×'+cv.height});}catch{toast('이미지를 읽지 못했어요. 파일을 확인해주세요.')}}persist();render();toast('이미지를 이 브라우저에 추가했어요.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();mobileOpen=false;render()}const modal=$('.modal');if(e.key==='Tab'&&modal){const els=[...modal.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
